-- AMBIGUITY: Subclass / archetype bonus lists (e.g. INFERNAL_SPELLS, SILVER_TONGUE_SWIFT) are not
-- flattened here. Swiftgard applies some of those client-side when a subclass is active.
-- To model them in Supabase, add rows to class_spell_rules with a dedicated source_type and teach
-- the app to surface them when the user selects the matching archetype.

-- SPELLS: Upsert canonical spell text. Adjust column list if your public.spells table differs.
      "May this armor protect thee from all forms of harm. 
      May the flames of the fire not burn thee.
      May the bolts from the heavens not strike thee.
      May the arrows of your enemies not pierce thee.
      May this armor protect thee from all forms of harm."', 'The effects of a Magic Ball, projectile weapon, or melee weapon which just struck armor worn by the player are ignored, even if the object would not otherwise affect the armor. The armor loses one point of value in the location struck. This effect will not trigger if the armor has no points left in the location struck. Ancestral Armor is not expended after use and will continue to provide protection until removed with Dispel Magic or similar abilities.', 'Phase Arrow and Phase Bolt interact with armor worn by the bearer as though Ancestral Armor was not present.', 'Engulfing Effects that do not strike the bearers armor and abilities that ignore armor entirely do not trigger Ancestral Armor.'),
(8, 'Agoraphobia', 'Verbal', 'Command', '20''', null, '"I command thee to be alone" x3', 'Target must remain at least 20'' away from all other living players unless forced there by another ability. Lasts 30 seconds.', null, null),
(9, 'Apex', 'Archetype', 'Neutral', null, null, null, 'Gain Mend 1/Life (ex) and Sleight of Mind (Self) 1/Life (ex)', 'Loses all instances of Evolution, Hold Person, Pinning Arrow.', null),
(10, 'Artificer', 'Archetype', 'Neutral', null, null, null, 'May wield a Small shield. Gain Greater Mend 2/Refresh Charge x10 (ex). Mend becomes 2/Life Charge x3 (ex). Casting Mend on weapons or shields does not consume a use of Mend.', 'Rather than the normal amount of Specialty Arrows for an Archer, gain: - Pinning Arrow 3 Arrows / Unlimited (ex) - Phase Arrow 1 Arrow / Unlimited (ex) - Suppression Arrow 1 Arrow/ Unlimited (ex) Look the Part becomes a fourth Pinning Arrow.', 'Player must still have a use of Mend remaining to cast on weapons or shields.'),
(11, 'Assassinate', 'Verbal', 'Death', '50''', null, '"Assassinate"', 'The target is Cursed.', 'May only be used immediately upon killing an enemy.', 'Assassinate targets the killed enemy and does not require verbal targeting.'),
(12, 'Astral Intervention', 'Verbal', 'Command', '20''', null, '"I command thee to retreat into the aether" x3', 'Target player becomes Insubstantial for 30 seconds.', null, 'If cast on self, the caster may end this Insubstantial State at any time by using the exit incantation for Insubstantial.'),
(13, 'Banish', 'Verbal', 'Spirit', '20''', null, '"The spirits banish thee from this place" x3', 'Target Insubstantial player must return to their base where their Insubstantial State immediately ends.', null, 'The target''s Insubstantial State is replaced with a new Insubstantial State from Banish. If the Insubstantial State is ended before reaching the base, the rest of the effect is ended as well. If Banish is cast on self, the caster may end this Insubstantial State at any time by using the exit incantation for Insubstantial.'),
(14, 'Barkskin', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee with barkskin" x3', 'Bearer gains one point of Magic Armor.', null, null),
(15, 'Battlefield Triage', 'Enchantment', 'Spirit', 'Touch', null, '"Be a bastion of healing" x3', 'Bearer may cast Heal (m) by incanting "<Player> thou art made whole" and removing an enchantment strip. Enchantment is removed when the last strip is removed.', null, null),
(17, 'Attuned', 'Enchantment', 'Sorcery', null, 'Yellow strip', '"I enchant thee with attune" x3', 'May wear an additional Enchantment. Attuned does not count towards the bearer''s Enchantment limit.', 'This ability may not be used in conjunction with any other similar ability.', 'If Attuned is removed, the bearer chooses which (m) Enchantments to lose to meet their new Enchantment limit, if necessary.'),
(18, 'Battlemage', 'Archetype', 'Neutral', null, null, null, 'Use of Ambulant becomes unlimited.', 'May not purchase Enchantments or Magic Balls.', null),
(19, 'Avatar of Nature', 'Archetype', 'Neutral', null, null, null, 'All the casters Enchantments of level 4 and below are now range Self instead of their previous range. Does not apply to Golem.', null, null),
(20, 'Awe', 'Verbal', 'Command', '20''', null, '"I command thee awed" x3', 'Target may not attack or cast Magical abilities at the caster or their carried equipment. Target must remain at least 20'' away from the caster unless forced there by another ability. Lasts 30 seconds.', null, 'If the caster attacks the target, begins casting another Magical ability at the target or their carried equipment, or dies, this ability''s effect is negated.'),
(21, 'Berserk', 'Enchantment', 'Sorcery', 'Self', 'Red strip', null, 'Bearer''s wielded melee weapons are Armor Breaking.', null, null),
(22, 'Berserker', 'Archetype', 'Neutral', null, null, null, 'Gain Momentum Unlimited (ex) (Ambulant).', 'May not wear Armor, and loses all instances of Blood and Thunder.', null),
(23, 'Blessed Aura', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thy person, arms, and armor" x3', 'Resistant to all effects from the next source which would inflict a wound, death, State, or negatively affect them or their carried equipment. Does not trigger against effects cast by the player.', null, null),
(24, 'Call Lightning', 'Verbal', 'Flame', '20''', null, '"I call lightning''s flame to strike thee" x3', 'Target player dies.', null, null),
(25, 'Blessing Against Harm', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee against all harm" x3', 'Resistant to all effects from the next source which would inflict a wound, death, State, or other negative effect. Does not trigger against effects cast by the player.', null, null),
(26, 'Blessing Against Wounds', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee against wounds" x3', 'Resistant to wounds. Does not count towards a players Enchantment limit.', 'May not be worn with any other Enchantments from the Protection School unless the other Enchantment is (ex).', null),
(27, 'Blink', 'Verbal', 'Sorcery', 'Self', null, '"I vanish from sight"', 'Player becomes Insubstantial. While Insubstantial in this
      way, player can move as they wish as long as they remain
      within 50'' from their starting point.', 'Caster may not end State within 10'' of a living enemy.', 'If the Insubstantial State is ended, the rest of the effect
      is ended as well. Caster may end this Insubstantial State
      at any time by using the exit incantation for Insubstantial.'),
(28, 'Circle of Protection', 'Verbal', 'Protection', 'Touch', null, '"Circle of Protection" x3', 'The caster and up to five willing players within Touch range of the caster immediately have all States and Ongoing Effects removed and then become Insubstantial.
      
>>All targets:
      
>> - May not move from their starting location, and are unaffected by abilities that allow or require the player to move.
      
>> - May use abilities on players and their carried equipment who became Insubstantial due to the same casting of Circle of Protection as though they were not Insubstantial.
      
>> - May end this Insubstantial State at any time by using the exit incantation for Insubstantial.
      The caster may end Circle of Protection for all targets at any time by using the exit incantation for Insubstantial.
      If the Insubstantial State is ended for a target, the Ongoing Effects of Circle of Protection no longer apply to that player.', null, 'If a player is prevented from becoming Insubstantial, they are unaffected by Circle of Protection.'),
(29, 'Combat Caster', 'Archetype', 'Neutral', null, null, null, 'Does not require an empty hand to cast abilities', null, null),
(30, 'Blood and Thunder', 'Verbal', 'Spirit', 'Self', null, '"Blood and Thunder!"', 'Player gains Blessing Against Wounds (ex).', 'Kill Trigger.', 'Player must still wear a white strip to denote Blessing Against Wounds.'),
(31, 'Break Concentration', 'Verbal', 'Command', '20''', null, '"I command thee suppressed"', 'Target player is Suppressed for 10 seconds.', null, null),
(32, 'Brutal Strike', 'Verbal', 'Death', 'Unlimited', null, '"And stay down!"', 'Target is Cursed. Target is also Suppressed for 30 seconds.', 'Wound Trigger.', 'Brutal Strike targets the wounded or dead player and does not require verbal targeting.'),
(33, 'Confidence', 'Verbal', 'Sorcery', 'Other', null, '"My power grants thee confidence"', 'Target player may instantly Charge a single ability.', 'May not be used within 20'' of a living enemy.', null),
(34, 'Contagion', 'Enchantment', 'Death', 'Other', 'Red strip', '"May thou bear this plague to all" x3', 'Bearers wielded melee weapons are Wounds Kill. Bearer is Fragile.', null, null),
(35, 'Corrosive Mist', 'Enchantment', 'Death', 'Touch', 'Three red strips', '"The mists of corrosion surround thee" x3', 'Bearer may cast Destroy Armor (m) by incanting "<player> the mists of corrosion destroy your <armor location> armor" and removing an enchantment strip. Enchantment is removed when the last strip is removed.', null, null),
(36, 'Corruptor', 'Archetype', 'Neutral', null, null, null, 'Gain Void Touched (Self) 2/Refresh (m). All uses of Terror become 1/Life Charge x10 (m).', 'May not wield Great Weapons or Javelins and loses all instances of Flame Blade.', null),
(37, 'Destruction Arrow', 'Specialty Arrow', 'Sorcery', null, 'Arrow with red head cover labeled ''Destruction''', '"Destruction Arrow"', 'This arrow is Armor Destroying and Shield Destroying. Armor Destroying and Shield Destroying are applied after the normal effect of being hit with an arrow is applied.', null, null),
(38, 'Dimensional Rift', 'Verbal', 'Sorcery', '20''', null, '"The power of the aether consumes thee" x3', 'Target insubstantial player dies.', null, null),
(39, 'Coup de Grace', 'Verbal', 'Death', '20''', null, '"Death shall come for thee" x3', 'Target player dies.', 'Target must be wounded when the caster begins the Incantation.', 'Even if the target has no wounds at the end of the Incantation they will still die.'),
(40, 'Dervish', 'Archetype', 'Neutral', null, null, null, 'Equipment costs are doubled. Each Verbal purchased gives double the uses. Example: 1/Life Charge x3 becomes 2/Life Charge x3, 2/Life becomes 4/Life, 1/Refresh becomes 2/Refresh.', null, null),
(41, 'Destroy Armor', 'Verbal', 'Death', '20''', null, '"Death destroys thy [hit location] armor" x3', 'Remove all armor points from target hit location.', null, 'Destroy Armor targets the player but affects the Hit Location. Visibility can be drawn to any part of the player, not just the desired Hit Location. Immunities, resistances, and other protections will only protect the armor from Destroy Armor if they specifically extend to the armor, such as Blessed Aura. Abilities like Enlightened Soul, Protection from Magic, and Adaptive Protection (Death) do not extend to armor and thus cannot protect against Destroy Armor. Ancestral Armor does not protect against verbal magic and thus cannot protect against Destroy Armor.'),
(42, 'Discordia', 'Enchantment', 'Command', 'Self', 'Five red strips', '"My discordant melodies shall stymie my foes" x3', 'Bearer may cast Break Concentration (m) by incanting "<Player> thou art suppressed" and removing an enchantment strip. Enchantment is removed when the last strip is removed.', null, null),
(43, 'Dispel Magic', 'Verbal', 'Sorcery', '20''', null, '"By my power I dispel that magic" x3', 'All Enchantments on target are removed.', null, 'Will always remove Enchantments if successfully cast on a valid target, regardless of the player''s Traits, States, Immunities, Ongoing Effects, or Enchantments (except Sleight of Mind).'),
(44, 'Dragged Below', 'Verbal', 'Death', '20''', null, '"Death comes for thee from below" x3', 'Target Stopped player dies.', null, null),
(45, 'Elemental Barrage', 'Verbal', 'Sorcery', 'Self', null, '"I am filled with the power of magic"', 'Caster may use Magic Balls they are currently carrying by stating the name of the Magic Ball immediately prior to throwing the ball in place of the incantation.', 'This magic ends if the caster picks up any additional
      Magic Balls or begins casting any new Magical abilities.', 'The effect is not an incantation, and so is not stopped
      by being Suppressed, and may be used while moving, etc.'),
(46, 'Empower', 'Verbal', 'Sorcery', 'Other', null, '"I empower thee"', 'Target player regains one use of any per-life ability they have expended.', null, null),
(47, 'Enlightened Soul', 'Enchantment', 'Protection', 'Other', 'White strip', '"A distant magic has no hold upon thy now enlightened soul" x3', 'Player is unaffected by Verbal Magical abilities used at a Range greater than Touch.', 'Affects beneficial as well as harmful Magical abilities.', 'Does not affect (ex) abilities, abilities with a Range of Touch, nor abilities whose Range is greater than Touch but are used at a Range of Touch anyway.'),
(48, 'Entangle', 'Magic Ball', 'Subdual', null, 'Brown Magic Ball', '"The strength of earth is mine to evoke" x3', 'Target is Stopped for 60 seconds. Engulfing.', null, null),
(49, 'Equipment: Armor, 1 Point', 'Neutral', null, null, null, null, 'Your class maximum armor limit increases one additional point.', null, null),
(50, 'Equipment: Shield, Medium', 'Neutral', null, null, null, null, 'May wield up to a Medium shield.', null, null),
(51, 'Equipment: Shield, Small', 'Neutral', null, null, null, null, 'May wield a Small shield.', null, null),
(52, 'Equipment: Weapon, Short', 'Neutral', null, null, null, null, 'May wield one Short weapon at a time for each instance purchased (but may carry extras).', null, null),
(53, 'Essence Graft', 'Enchantment', 'Sorcery', 'Other', 'Yellow strip', '"I enchant thee with essence graft" x3', 'Bearer may wear up to three additional Enchantments. Essence Graft does not count towards the bearer''s Enchantment limit.', 'Bearer may only wear (m) Enchantments from the caster of Essence Graft. This ability may not be used in conjunction with any other similar abilities.', 'If Essence Graft is removed, the bearer chooses which (m) Enchantments to lose to meet their new Enchantment limit, if necessary.'),
(54, 'Evoker', 'Archetype', 'Neutral', null, null, null, 'May not purchase Verbals with a range of 20'' or 50''. Elemental Barrage becomes Charge x10.', null, 'Elemental Barrage must still be purchased.'),
(55, 'Evolution', 'Enchantment', 'Sorcery', 'Self', null, null, 'May wear an additional Enchantment. Evolution does not count towards the bearer''s Enchantment limit.', null, 'This ability does work in conjunction with Attuned, Essence Graft, or Phoenix Tears so long as the other limitations of those Enchantments are followed.'),
(56, 'Experienced', 'Neutral', 'Neutral', null, null, null, 'A single per-life Verbal purchased becomes Charge x5 in addition to the normal frequency OR a single per-refresh Verbal purchased becomes Charge x10 in addition to the normal frequency. This Verbal must be determined before the game begins and cannot be changed.', 'Verbal must be 4th level or lower.', null),
(57, 'Extend Immunities', 'Enchantment', 'Protection', 'Other', 'White strip', '"May the blessing of my god protect thee" x3', 'The target player gains either Immune to Command or Immune to Death.', 'Type of ability must be chosen at the time of casting and may not be changed. The caster may only have one instance of Extend Immunities at a time.', null),
(58, 'Extension', 'Meta-Magic', 'Neutral', null, null, '"Extension"', 'Verbal becomes 50''. Only works on Verbals with a range of 20''.', null, null),
(59, 'Finger of Death', 'Verbal', 'Death', '20''', null, '"I call upon death to smite thee" x3', 'Target player dies.', null, null),
(60, 'Fireball', 'Magic Ball', 'Flame', null, 'Red Magic Ball', '"The flame of fire is mine to evoke" x3', 'Fireball will have one of the following effects on the object first struck:
    
>> 1. A weapon hit is destroyed
    
>> 2. A Shield hit is subject to Shield Destroying
    
>> 3. Armor hit with Armor Points remaining is subject to Armor Destroying.
    
>> 4. A player hit dies.', null, null),
(61, 'Force Bolt', 'Magic Ball', 'Sorcery', null, 'Blue Magic Ball', '"Forcebolt" x3', 'Force Bolt will have one of the following effects on the object first struck:
    
>> 1. A weapon hit is destroyed
    
>> 2. Armor hit with Armor Points remaining is subject to Armor Breaking.
    
>> 3. A player hit receives a wound to that hit location.', null, null),
(62, 'Gift of Air', 'Enchantment', 'Protection', 'Other', 'White strip', '"I grant thee a gift of the air" x3', 'The effects of any weapon or ammunition which just struck the bearer are ignored, instead the bearer declares "Gift of Air" and becomes Insubstantial. If the bearer is wearing armor it is affected as normal in addition to triggering Gift of Air. Bearer may choose to return directly to their base immediately after Gift of Air activates. Melee weapons with the Siege, Armor Breaking, Armor Destroying, Shield Crushing, or Shield Destroying Special Effects will affect the bearer as normal and do not trigger Gift of Air.', 'Bearer may not wield weapons or Shields.', 'If the Insubstantial State is ended, the player is not required to continue returning to base. Bearer may end this Insubstantial State at any time by using the exit incantation for Insubstantial.'),
(63, 'Gift of Earth', 'Enchantment', 'Protection', 'Other', 'White strip', '"I grant thee a gift of the earth" x3', 'Bearer gains one point of Magic Armor and is affected as per Harden.', null, null),
(64, 'Gift of Fire', 'Enchantment', 'Flame', 'Other', null, '"I grant thee a gift of the fire" x3', 'Bearer gains Heat Weapon 1/Refresh Charge x3 (m) and is Immune to Flame.', null, null),
(65, 'Flame Blade', 'Enchantment', 'Flame', 'Other', 'Red strip and white strip', '"The element of fire shall infuse your weapons" x3', 'Bearer''s wielded melee weapons are Armor Breaking and Shield Crushing. Bearer and their wielded weapons are Immune to Flame.', null, null),
(66, 'Force Barrier', 'Verbal', 'Sorcery', 'Self', null, '"I shall not be harmed"', 'Player is Frozen for 10 seconds.', null, null),
(67, 'Gift of Water', 'Enchantment', 'Sorcery', 'Other', 'White strip and yellow strip', '"I grant thee a gift of the water" x3', 'Bearer gains one point of Magic Armor and Heal (Self) Unlimited (m).', null, null),
(68, 'Golem', 'Enchantment', 'Sorcery', 'Other', 'White strip and yellow strip', '"From earth and clay I form thee" x3', 'Bearer is Immune to Death. Bearer is Cursed. Bearer can remove a wound via Mend. Bearer may use the caster as an alternate respawn point while the caster is alive. Bearer may treat the caster as a base for the purposes of the effects which require the bearer to go to their base. Non-magical armor worn affected as per Imbue Armor. All Enchantments worn by the Bearer, including Golem, are Persistent while Golem is worn.', 'A caster may only have a single Golem Enchantment at a time.', 'Greater Mend and Word of Mending will not remove a wound.'),
(69, 'Greater Harden', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee with Greater Harden" x3', 'Shields and weapons wielded by the player are affected as per Harden.', null, null),
(70, 'Greater Heal', 'Verbal', 'Spirit', 'Touch', null, '"By the grace of the divine thou art healed" x5', 'All wounds are healed. Ignores the Cursed State.', null, null),
(71, 'Greater Mend', 'Verbal', 'Sorcery', 'Touch', null, '"Return this <object name> to its former glory" x5', 'Will restore all armor points in one location or repair a damaged or broken item.', null, null),
(72, 'Greater Resurrect', 'Verbal', 'Spirit', 'Other', null, '"By the grace of the divine thou art resurrected" x5', 'Target dead player who has not moved more than 5'' from where they died is returned to life. Any wounds on the player are healed. Works regardless of any States on the target, and removes Cursed if present.', null, 'Enchantments on the player are retained.'),
(73, 'Guardian', 'Archetype', 'Neutral', null, null, null, 'Gain Imbue Shield (Touch) 1/Life (m) and Martyr (Other) 2/Life Charge x3 (ex).', 'Loses all instances of Protection from Magic and Extend Immunities. May only have one instance of Imbue Shield active at a time.', null),
(74, 'Harden', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee with Harden" x3', 'Bearer''s wielded weapons or shield may only be destroyed or damaged by Magic Balls/Verbals which destroy objects e.g. Fireball or Pyrotechnics.', 'Will only affect either the weapons or the shield of the bearer, not both.', null),
(75, 'Heal', 'Verbal', 'Spirit', 'Touch', null, '"The white light of healing hath healed thee." x5', 'Target player heals a wound.', null, null),
(76, 'Greater Release', 'Verbal', 'Sorcery', '20''', null, '"From all thine afflictions thou art released" x2', 'All Ongoing Effects and States are removed from the target. The caster may choose to leave some States or Effects in place. Greater Release may target Dead players.', null, 'When used to end a State or Ongoing Effect imposed by an ability with multiple effects, all other States and Ongoing Effects from the same source are also ended.'),
(77, 'Heart of the Swarm', 'Enchantment', 'Spirit', 'Self', 'Yellow strip', '"Let all those who oppose the hive feel the wrath of the swarm" x3', 'Bearer is Stopped. Any player on the bearer''s team may use the bearer as their respawn point as per the normal game rules. Players respawning at the caster do so by announcing "My life for the swarm." Players on the bearer''s team may treat the bearer as a base for the purposes of the effects which require the teammate to go to their base.', 'Players cannot respawn at the bearer if there are living enemy players or a game objective within 20'' of the bearer.', null),
(78, 'Heat Weapon', 'Verbal', 'Flame', '20''', null, '"I call upon flame to heat that [type of weapon]" x3', 'Target weapon may not be wielded for 30 seconds. Players who are Immune to Flame may continue to wield the weapon.', null, 'The equipment, not the person, is the target of Heat Weapon. The equipment is the only thing required to be within range and visible for this ability to affect it.'),
(79, 'Hold Person', 'Verbal', 'Command', '20''', null, '"I command thee to stop" x3', 'Target player becomes Stopped for 30 seconds.', null, null),
(80, 'Hunter', 'Archetype', 'Neutral', null, null, null, 'May wield Great weapons and Javelins. Pick one: -Hold Person becomes 1/Life Charge x3 (m). -Pinning Arrow becomes 2 Arrows / Unlimited (ex)', 'May not wield shields. Loses all instances of Release and Evolution.', 'You only gain the benefit of an option if you already have that ability.'),
(81, 'Imbue Shield', 'Enchantment', 'Protection', 'Other', 'White strip', '"This Shield shall neither bend nor break" x3', 'Shield wielded by the player cannot be destroyed nor damaged. Engulfing effects hitting the wielded shield are ignored.', null, null),
(82, 'Iceball', 'Magic Ball', 'Subdual', null, 'White Magic Ball', '"The strength of ice is mine to evoke" x3', 'Target player becomes Frozen for 60 seconds. Engulfing.', null, null),
(83, 'Icy Blast', 'Verbal', 'Sorcery', '20''', null, '"My power makes thee frozen" x3', 'Target player becomes Frozen for 30 seconds.', null, null),
(84, 'Imbue Armor', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee with Imbued Armor" x3', 'Armor worn by the bearer gains 1 Armor Point to its current and maximum rating in each location, up to the bearer''s class maximum.', 'Does not apply to Magic Armor. A player may only benefit from one instance of Imbue Armor.', 'When this enchantment is removed, the bearer loses 1 current and maximum Armor Point in each location.'),
(85, 'Infernal', 'Archetype', 'Neutral', null, null, null, 'Gain Fireball 2 Balls / Unlimited (m). Flame Blade becomes (Self) 2/Refresh Charge x5.', 'May not wield shields. Lose all instances of Steal Life Essence.', null),
(86, 'Innate', 'Meta-Magic', 'Neutral', null, null, '"Innate"', 'May be used to instantly Charge a single ability by stating its name.', null, null),
(87, 'Inquisitor', 'Archetype', 'Neutral', null, null, null, 'Gain Sacred Blades (Self) 1/Life (ex)', 'Player loses all instances of Greater Resurrect.', null),
(88, 'Insult', 'Verbal', 'Command', '20''', null, '"I command thy attention" x3', 'Target is unable to attack or cast Magical abilities at anyone other than the caster or their carried equipment for 30 seconds, or until either party dies. If the target of Insult is attacked or has Magical abilities cast on them or their carried equipment by someone other than the caster, the target of Insult becomes able to choose to attack the offending party as well.', null, 'The target may still charge and throw Magic Balls at the caster.'),
(89, 'Ironskin', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee with Ironskin" x3', 'Bearer is Immune to Flame and gains two points Magic Armor affected as per Ancestral Armor.', null, null),
(90, 'Juggernaut', 'Archetype', 'Neutral', null, null, null, 'Replace Harden with Greater Harden (Self) (ex) at the same frequency. Gain Phoenix Tears (Self) 3/Refresh (ex) (Swift) and Imbue Armor (T).', 'Loses all instances of Ancestral Armor and True Grit.', null),
(91, 'Legend', 'Archetype', 'Neutral', null, null, null, 'Each Extension purchased gives double the uses. Example: 1/Life becomes 2/Life. Swift may not be purchased or used.', null, null),
(92, 'Lightning Bolt', 'Magic Ball', 'Flame', null, 'Yellow Magic Ball', '"The flame of storms is mine to evoke" x3', 'A player struck is subject to an Engulfing Stopped effect for 60 seconds. In addition Lightning Bolt will have one of the following effects on the object first struck:
    
>> 1. A weapon hit is destroyed
    
>> 2. Armor hit with Armor Points remaining is subject to Armor Breaking.
    
>> 3. A player hit receives a wound in that hit location.', null, null),
(93, 'Lost', 'Verbal', 'Command', '20''', null, '"I command thee to be lost" x3', 'Player becomes Insubstantial and must move directly to their base. Player must end their Insubstantial State as per normal once they reach their base.', null, 'If the Insubstantial State is ended before reaching the base, the rest of the effect is ended as well. If Lost is cast on self, the caster may end this Insubstantial State at any time by using the exit incantation for Insubstantial.'),
(94, 'Lycanthropy', 'Enchantment', 'Death', 'Other', 'White strip and red strip', '"I enchant thee with Lycanthopy" x3', 'Bearer gains two points of magic armor. Bearer''s wielded melee weapons are Shield Crushing. Bearer is Immune to Command.', null, null),
(95, 'Martyr', 'Verbal', 'Spirit', 'Other', null, '"Thy burdens are mine to bear."', 'A single State is removed from target willing player. The caster gains the removed State with a new duration of 10 seconds.', 'Cannot be cast while Cursed. Caster may not remove themselves from Insubstantial states gained this way.', null),
(96, 'Mass Healing', 'Enchantment', 'Spirit', 'Self', 'Five yellow strips', '"Let the powers of healing flow through me" x3', 'Caster may Heal (m) a player at Touch by stating "I grant thee healing" and removing an enchantment strip. Enchantment is removed when the last strip is removed.', null, 'The effect is not an incantation, and so is not stopped by being Suppressed, and may be used while moving, etc.'),
(97, 'Medium', 'Archetype', 'Neutral', null, null, null, 'Gain Blessing Against Wounds (Touch) 1/Life (ex), Sever Spirit 1/Life Charge x3 (ex), and Swift 2/Life (ex). Abilities in the Spirit school become Charge x3.', 'May not wear Armor and may not wield Great weapons.', null),
(98, 'Mend', 'Verbal', 'Sorcery', 'Touch', null, '"I make this item whole again" x5', 'Destroyed or damaged item is repaired, or one point of armor in one location is repaired.', null, null),
(99, 'Missile Block', 'Enchantment', 'Protection', 'Self', null, null, 'Player may block arrows, projectile weapons, and Magic Balls with their hands and wielded melee or thrown weapons. Any arrow, projectile weapon or magic ball blocked is nullified.', null, null),
(100, 'Momentum', 'Verbal', 'Sorcery', 'Self', null, '"Momentum"', 'May be used to instantly Charge a single ability by stating its name.', 'Kill trigger.', null),
(101, 'Mutation', 'Enchantment', 'Sorcery', 'Self', null, null, 'Enchantments worn by the player are Persistent.', null, null),
(102, 'Mystic', 'Archetype', 'Neutral', null, null, null, 'Gain Force Bolt 4 Balls / Unlimited (m). Gain Suppression Bolt 2 Balls / Unlimited (m).', 'May not wield Heavy Thrown. Lose all instances of Resurrect.', null),
(103, 'Naturalize Magic', 'Enchantment', 'Sorcery', 'Self', 'Three red strips', '"I shall restore the balance" x3', 'Bearer may cast Dispel Magic (m) by incanting "<player> thou art dispelled" and removing an enchantment strip. Enchantment is removed when the last strip is removed.', null, null),
(104, 'Necromancer', 'Archetype', 'Neutral', null, null, null, 'All abilities purchased in the Death School become Charge x3. You may have a combined total of five Undead Minion Enchantments.', 'You may not purchase any abilities from the Protection School.', null),
(105, 'Persistent', 'Meta-Magic', 'Neutral', null, null, '"Persistent"', 'Enchantment returns with the user after respawning until it has been otherwise removed.', null, 'Persistent is a Meta-Magic; it must be used before another incantation, and affects the next ability cast by that same caster. Persistent does not retroactively make an enchantment already on a player Persistent. Persistent Enchantments with limited uses (Mass Healing, Corrosive Mist, etc.) will retain the number of uses they had remaining. Persistent Magic Armor behaves like normal armor: it will be repaired upon respawning or retain any prior damage if the bearer is returned to life by some other method, such as Resurrect.'),
(106, 'Phase Arrow', 'Specialty Arrow', 'Sorcery', null, 'Arrow with gray cover labeled ''Phase''', '"Phase Arrow"', 'This arrow does not interact with other ongoing abilities nor Traits. Example: This arrow is not stopped by Stoneskin, Protection from Projectiles, and does not trigger the effects of Gift of Air, Troll Blood, Missile Block, or similar abilities.', 'This arrow does not supercede the Frozen, Insubstantial, or Invulnerable States.', null),
(107, 'Phase Bolt', 'Magic Ball', 'Sorcery', null, 'Gray Magic Ball', '"The power of sorcery is mine to evoke" x3', 'This Magic Ball does not interact with other ongoing abilities nor Traits. Example: This Magic Ball is not stopped by Stoneskin, Protection from Projectiles, and does not trigger the effects of Gift of Air, Troll Blood, Missile Block, or similar abilities.
    
>>Will have one of the following effects:
    
>> 1. A weapon hit is destroyed
    
>> 2. Armor hit with Armor Points remaining is subject to Armor Breaking.
    
>> 3. A player hit receives a wound in that hit location.', 'Does not supercede the Frozen, Insubstantial, or Invulnerable States.', null),
(108, 'Phoenix Tears', 'Enchantment', 'Spirit', 'Other', 'Two white strips', '"May the tears of the phoenix wash over thee" x3', 'Enchanted player does not die as normal. When the player would otherwise die they instead remove a strip and become Frozen for 30 seconds. 
    
>>When the Frozen State is ended, the bearer is affected as follows:
    
>> 1. All wounds are removed.
    
>> 2. All States that would be removed by death or Respawning are removed.
    
>> 3. All Ongoing Effects with a timer expire.
    
>> 4. All of their carried equipment is fully repaired.
    
>> 5. All non-persistent enchantments, other than Phoenix Tears, are removed.
Additionally Phoenix Tears allows you to wear an extra Enchantment from the Protection School. This extra enchantment is considered Persistent as long as Phoenix Tears is present. The additional Enchantment is not removed once Phoenix Tears is removed.', 'Phoenix Tears is removed when the last strip is removed. If Phoenix Tears is removed, the bearer chooses which (m) Enchantments to lose to meet their new Enchantment limit, if necessary.', null),
(109, 'Pinning Arrow', 'Specialty Arrow', 'Sorcery', null, 'Arrow with yellow head cover labeled ''Pinning''', '"Pinning Arrow"', 'A player struck by this arrow is Stopped for 30 seconds. Engulfing.', null, null),
(110, 'Planar Grounding', 'Verbal', 'Sorcery', '20''', null, '"My power closes the aether to you" x3', 'Target player has their Insubstantial State removed and may not become Insubstantial for 30 seconds. May be cast on players who are not currently Insubstantial.', null, 'Planar Grounding causes Enchantments that automatically render their bearer Insubstantial, such as Gift of Air, to fail and be removed if they activate while Planar Grounding is in effect.'),
(111, 'Poison', 'Enchantment', 'Death', 'Self', 'Red strip', '"I coat these weapons with a deadly poison" x2', 'The next wound dealt by the bearer with a wielded melee weapon is Wounds Kill.', null, 'If the target does not actually receive a wound, e.g. by a Resistance, Poison is not expended.'),
(112, 'Poison Arrow', 'Specialty Arrow', 'Death', null, 'Arrow with green head cover labeled ''Poison''', '"Poison Arrow"', 'This arrow is Wounds Kill.', null, null),
(113, 'Poison Glands', 'Enchantment', 'Death', 'Other', 'Red strip', '"Thou shalt secrete poison from thy venemous glands" x3', 'Bearer gains Poison (Self) 1/Refresh Charge x3 (ex).', null, null),
(114, 'Priest', 'Archetype', 'Neutral', null, null, null, 'Meta-Magic may only be used on Spirit abilities. All Meta-Magics purchased become 1/Life Charge x3. Heal costs zero points.', null, null),
(115, 'Pyrotechnics', 'Verbal', 'Flame', '50''', null, '"I call upon the element of flame to destroy thy belongings" x3', 'All shields and weapons carried by the target player are destroyed.', 'Only affects shields and weapons carried when the Verbal is completed.', 'Pyrotechnics targets the player but affects their equipment. Immunities, resistances, and other protections will only protect the equipment from Pyrotechnics if they specifically extend to the equipment, such as Blessed Aura or Flame Blade. Abilities like Enlightened Soul, Protection from Magic, and Adaptive Protection (Flame) do not extend to equipment and thus cannot protect from Pyrotechnics.'),
(116, 'Rage', 'Verbal', 'Sorcery', 'Self', null, '"I am filled with rage!"', 'Caster is unaffected by Verbal abilities and their wielded melee weapons are Shield Crushing and Armor Breaking for seven seconds. Caster must count this time out loud, audible to 50''; failure to count ends the effect.', null, null),
(117, 'Raider', 'Archetype', 'Neutral', null, null, null, 'Gain Bear Strength (Self) 1/Life (ex). Look the part becomes an additional use of Brutal Strike.', 'Loses all instances of Rage.', null),
(118, 'Protection from Magic', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee with protection from magic" x3', 'Bearer is unaffected by Magical abilities from any school. Upon death the player is Cursed.', null, 'This effect does not interact with other Enchantments worn by the bearer.'),
(119, 'Protection from Projectiles', 'Enchantment', 'Protection', 'Other', 'White strip', '"I enchant thee with Protection from Projectiles" x3', 'Bearer is unaffected by ammunition, thrown javelins, rocks, and thrown weapons. Engulfing effects from those objects, such as Pinning Arrow, do not affect the player.', null, 'Equipment can still be affected by the above. Does not protect bearer against Magic Balls.'),
(120, 'Raise Dead', 'Verbal', 'Death', 'Touch', null, '"Rise and fight again" x5', 'Target dead player who has not moved more than 5'' from where they died is returned to life and is Cursed. Target is also Suppressed for 30 seconds. Non-Persistent Enchantments on the player are removed before the player returns to life. Any wounds on the player are healed.', null, null),
(121, 'Ranger', 'Archetype', 'Neutral', null, null, null, 'May use Bows. The cost of all available Equipment is reduced to zero points. Enchantment costs are doubled.', null, null),
(122, 'Ravage', 'Verbal', 'Death', '20''', null, '"Death shall make thee fragile" x3', 'Target player is Fragile.', null, null),
(123, 'Regeneration', 'Enchantment', 'Spirit', 'Other', 'Yellow strip', '"I grant thee the power of regeneration" x3', 'Bearer gains Heal (Self) Unlimited (m) (Swift).', 'The Heal granted by Regeneration may not be used within 10'' of a living enemy.', 'Bearer must state Swift normally.'),
(124, 'Release', 'Verbal', 'Sorcery', 'Touch', null, '"From thy bindings thou art released" x5', 'A single Ongoing Effect or State is removed from the target. Casters choice.', 'Cannot remove Cursed. When used to end a State or Ongoing Effect imposed by an ability with multiple effects, all other States and Ongoing Effects from the same source are also ended.', null),
(125, 'Reload', 'Verbal', 'Sorcery', 'Self', null, '"I nocked my arrows to my bow, I let them fly, my quiver is low. Now I pause to go reload." x3', 'Player becomes Invulnerable and may move about the field retrieving their arrows. The player may remove their Invulnerable State in the location they started or at base by stating, "I return with a full quiver" x3.', 'Must stay at least 10'' away from other players at all times. A player may not exit Reload at an alternate base location, such as Heart of the Swarm, in this way.', 'May ask reeve for assistance in retrieving arrows that are within 10'' of other players.'),
(126, 'Restoration', 'Verbal', 'Sorcery', 'Other', null, '"I restore thee to thy full potency"', 'Player has all uses of their per-life abilities restored.', 'Does not function on Empower, Confidence, or Restoration.', null),
(127, 'Resurrect', 'Verbal', 'Spirit', 'Other', null, '
      "Sword Cut, spear stab, mace smash, arrow jab, 
      Let the white light of healing descend on thee. 
      Let the white light of healing stop thy spilling blood. 
      Let the white light of healing mend thy bones. 
      Let the white light of healing close thy wounds. 
      Let the white light of healing restore thy vigor. 
      The white light of healing hath resurrected thee."', 'Target dead player who has not moved more than 5'' from where they died is returned to life. Non-Persistent Enchantments on the player are removed before the player returns to life. Any wounds on the player are healed.', null, null),
(128, 'Sanctuary', 'Verbal', 'Protection', 'Self', null, '"Sanctuary"', 'Player and their carried equipment are unaffected by hostile actions originating from within 20''. Must Chant "sanctuary". Player may end Sanctuary at any time by ceasing to chant and declaring "No longer in sanctuary" or by picking up a weapon with their hand.', 'If the player is voluntarily touching (other than blocking) or carrying weapons in any fashion (tucked under arms, tied to thongs, etc) at any point during Sanctuary then they may only voluntarily end Sanctuary within 20'' of a friendly base, and must continue chanting until there. Player may not cast this ability while they have any weapons in hand. Cannot interact with game items nor game objectives, nor impede the play of other people in any manner, and must immediately move to avoid such situations. May not come within 20'' of a non-friendly base.', 'The exit declaration must be audible out to 20 feet.'),
(129, 'Scavenge', 'Verbal', 'Sorcery', 'Self', null, '"Scavenge"', 'Destroyed or damaged item is repaired, or one point of armor in one location is repaired.', 'Kill Trigger.', null),
(130, 'Sever Spirit', 'Verbal', 'Spirit', '20''', null, '"The spirits lay a curse on thee." x3', 'May only target dead players. Player is Cursed. Any Enchantments on the player are removed.', null, 'Will always remove enchantments if successfully cast on a valid target, regardless of the player''s Traits, States, Immunities, Ongoing Effects, or Enchantments.'),
(131, 'Shadow Step', 'Verbal', 'Sorcery', 'Self', null, '"I step into the shadows"', 'Player becomes Insubstantial. Shadow Step may be cast while moving.', null, 'Caster may end this Insubstantial State at any time by using the exit incantation for Insubstantial.'),
(132, 'Shake It Off', 'Verbal', 'Spirit', 'Self', null, '"I shall overcome"', '10 seconds after casting Shake It Off the player may remove from themselves any number of States or Ongoing Effects of their choice. Shake It Off may be cast at any time the player is alive, even while the player would otherwise be prevented from casting abilities by Stunned, Suppressed, or similar.', null, null),
(133, 'Shatter', 'Verbal', 'Sorcery', '20''', null, '"My power shatters thy body" x3', 'Target Frozen player dies.', null, null),
(134, 'Shove', 'Verbal', 'Sorcery', '20''', null, '"My power shoves thee" x3', 'Target player is moved back 20'' in a straight line away from the caster. Works on Stopped players. If the caster is the target, the caster may choose the direction they move.', null, null),
(135, 'Silver Tongue', 'Enchantment', 'Sorcery', 'Touch', 'Yellow strip', '"My power quickens thine" x3', 'Bearer gains Swift 1/Refresh Charge x3 (m). Other sources of Swift may not be utilized while Silver Tongue is worn.', null, 'Does not use up any purchased instances of Swift.'),
(136, 'Sleight of Mind', 'Enchantment', 'Sorcery', 'Other', 'Yellow strip', '"May thy power remain" x3', 'Enchantments worn by the bearer, other than Sleight of Mind, are not removed by Dispel Magic or similar abilities. Does not count towards the bearer''s Enchantment Limit.', null, null),
(137, 'Snaring Vines', 'Enchantment', 'Command', 'Self', 'Three red strips', '"The hands of the earth rise to your bidding" x3', 'Bearer may cast Hold Person (m) by incanting "<player> stop at my command" and removing an enchantment strip. Enchantment is removed when the last strip is removed.', null, null),
(138, 'Shatter Weapon', 'Verbal', 'Sorcery', '20''', null, '"My power destroys thy [type of weapon]" x3', 'Target weapon is destroyed.', null, 'The equipment, not the person, is the target of Shatter Weapon. The equipment is the only thing required to be within range and visible for this ability to affect it.'),
(139, 'Sniper', 'Archetype', 'Neutral', null, null, null, 'May physically carry any number of Specialty Arrows of each type. The frequency of each type of Specialty Arrow ability becomes 1 Arrow/Life Charge x3. Gain Momentum Unlimited (ex) (Ambulant). Look the part becomes Mend 1/Life.', 'May not fire normal arrows.', null),
(140, 'Song of Battle', 'Enchantment', 'Protection', 'Self', null, '"I sing of my legendary prowess"', 'Bearer''s wielded melee weapons are Armor Breaking. Bearer must Chant "Song of Battle" or sing a song regarding their martial prowess. Singing in place of the normal Chant is still a Chant and must follow all Chant rules.', null, null),
(141, 'Song of Deflection', 'Enchantment', 'Protection', 'Self', null, '"I sing of my nimble acrobatics"', 'Bearer is unaffected by ammunition, thrown Javelins, Rocks, and thrown weapons. Engulfing effects from those objects, such as Pinning Arrow, do not affect the player. Bearer must Chant "Song of Deflection" or sing a song of their acrobatic prowess. Singing in place of the normal Chant is still a Chant and must follow all Chant rules.', null, 'Does not protect the bearer against Magic Balls.'),
(142, 'Song of Determination', 'Enchantment', 'Protection', 'Self', null, '"I sing of my unwavering determination"', 'Bearer is Immune to Command. Bearer must Chant "Song of Determination" or sing a song regarding their determination. Singing in place of the normal Chant is still a Chant and must follow all Chant rules.', null, null),
(143, 'Song of Freedom', 'Enchantment', 'Protection', 'Self', null, '"I sing of my unquenchable wanderlust"', 'Bearer cannot receive the States Stopped, Frozen, or Insubstantial unless caused by the bearer or other enchantments they carry. Bearer must Chant "Song of Freedom" or sing a song of roving or rambling. Singing in place of the normal Chant is still a Chant and must follow all Chant rules.', null, null),
(144, 'Song of Interference', 'Enchantment', 'Protection', 'Self', null, '"I sing a song of dark magic thwarted"', 'As per Enlightened Soul. Bearer must Chant "Song of Interference" or sing a song about defeating/resisting the forces of magic. Singing in place of the normal Chant is still a Chant and must follow all Chant rules.', null, null),
(145, 'Song of Power', 'Enchantment', 'Protection', 'Self', null, '"I sing to inspire my comrades-in-arms"', 'Friendly players within 20'' of the bearer have their Charging Incantation repetitions divided by 2, rounded down, to a minimum of 1. Bearer is Stopped. Bearer must Chant "Song of Power" or sing an inspiring song. Singing in place of the normal Chant is still a Chant and must follow all Chant rules.', 'Players can only benefit from one instance of Song of Power at a time.', null),
(146, 'Song of Survival', 'Enchantment', 'Protection', 'Self', null, '"I sing of my numerous close calls"', 'When the bearer would otherwise die, they instead declare "Song of Survival" and become Insubstantial. The caster treats the triggering event as though it had no effect on them other than triggering Song of Survival. Song of Survival immediately ends and bearer must stop their Chant. Bearer may choose to return directly to their base immediately after Song of Survival activates. Bearer must Chant "Song of Survival" or sing a song regarding their many escapes from certain doom. Singing in place of the normal Chant is still a Chant and must follow all Chant rules.', 'Once Song of Survival has activated to protect the bearer it may not be cast nor activated again on the same life.', 'Bearer may end the Insubstantial State caused by Song of Survival at any time with the standard incantation. If the Insubstantial State is ended by any means before reaching the base, the rest of the effect is ended as well.'),
(147, 'Song of Visit', 'Enchantment', 'Protection', 'Self', null, '"I sing to entertain friend and foe" x3', 'Bearer cannot be wounded and is Immune to all Schools. Bearer is Stopped. Bearer must Chant "Song of Visit" or sing a song regarding their general good nature and friendly disposition. Singing in place of the normal Chant is still a Chant and must follow all Chant rules. When Song of Visit is removed player becomes Insubstantial and must immediately move directly to their base. Upon arrival, they must immediately end the effect as per Insubstantial.''', 'Bearer may not wield weapons, interact with game objects, impede play, gain further Enchantments, or target any player.', 'This Enchantment can be removed by Dispel Magic and similar abilities. If the Insubstantial State is ended, the rest of the effect is ended as well.'),
(148, 'Stun', 'Verbal', 'Sorcery', '20''', null, '"By the power of white light I stun thee" x3', 'Target player is Stunned for 30 seconds.', null, null),
(149, 'Sphere of Annihilation', 'Magic Ball', 'Sorcery', null, 'Black Magic Ball', '"The power of void is mine to evoke" x3', 'Sphere of Annihilation ignores armor and enchantments and will have one of the following effects on the object first struck:
    
>> 1. A weapon struck is destroyed
    
>> 2. A shield struck is subject to Shield Destroying.
    
>> 3. A player struck dies and is Cursed.', null, 'Does not ignore Traits, such as Missile Block.'),
(150, 'Spy', 'Archetype', 'Neutral', null, null, null, 'Blink and Shadow Step become Charge x3 (ex).', 'May not wear Armor.', null),
(151, 'Steal Life Essence', 'Verbal', 'Death', 'Touch', null, '"Steal life"', 'Caster may heal a wound or instantly Charge an ability. May only be used on a dead player. That player is Cursed.', 'Does not work on Cursed players. The caster does not gain the effect if the dead player is unaffected.', 'In order to charge an ability, the name of the ability being charged must still be stated immediately after the incantation.'),
(152, 'Stoneform', 'Verbal', 'Protection', 'Self', null, '"I take the form of stone"', 'Caster is Frozen. May end this State at any time by saying "The earth release me" x2.', null, null),
(153, 'Stoneskin', 'Enchantment', 'Protection', 'Other', 'White strip', '"May nature protect thee from all forms of attack" x3', 'Bearer gains 2 points of Magic Armor affected as per Ancestral Armor.', null, null),
(154, 'Summon Dead', 'Verbal', 'Spirit', '50''', null, '"I summon thy corpse" x5', 'Target willing dead player must go directly to the caster. Upon reaching the caster, Summon Dead immediately ends. Wherever the player is when Summon Dead ends is treated as where the player died.', 'May be used on a dead player who has not moved more than 5'' from where they died or who is at their respawn.', null),
(155, 'Summoner', 'Archetype', 'Neutral', null, null, null, 'Each Enchantment purchased gives double the uses. Example: 1/Life Charge x3 becomes 2/Life Charge x3, 2/Life becomes 4/Life.', 'May not purchase Verbals with a range other than Touch or Self. May not purchase equipment beyond 2nd level.', null),
(156, 'Suppress Aura', 'Verbal', 'Command', '50''', null, '"I command thee powerless" x3', 'Target is Suppressed for 30 seconds.', null, null),
(157, 'Suppression Arrow', 'Specialty Arrow', 'Sorcery', null, 'Arrow with purple head cover labeled ''Suppression''', '"Suppression Arrow"', 'A player struck by this arrow is Suppressed for 30 seconds. Engulfing.', null, null),
(158, 'Suppression Bolt', 'Magic Ball', 'Subdual', null, 'Purple Magic Ball', '"The strength of suppression is mine to evoke" x3', 'Target is Suppressed for 60 seconds. Engulfing.', null, null),
(159, 'Swift', 'Meta-Magic', 'Neutral', null, null, '"Swift"', 'Abilities require only a single iteration of the incantation. For multi-line Incantations use the last line.', 'May only be used on abilities at a range of Touch, Other, Self, or on Magic Balls. May not be used on the Charge Incantation.', null),
(160, 'Teleport', 'Verbal', 'Sorcery', 'Touch', null, '"I travel through the aether" x5', 'Target willing player becomes Insubstantial and moves directly to a chosen location chosen by the caster at the time of casting. This must be a fixed location (not relative to a player or to a moveable object). Upon arrival, they must immediately end the effect as per Insubstantial.', null, 'If the player''s Insubstantial State is removed before they have reached their destination, the effects of Teleport end. If Teleport is cast on self, the caster may end this Insubstantial State at any time by using the exit incantation for Insubstantial.'),
(161, 'Terror', 'Verbal', 'Death', '20''', null, '"Death makes thee terrified" x3', 'Target may not attack or cast Magical abilities at the caster or their carried equipment. Target must remain at least 50'' away from the caster unless forced there by another ability. Lasts 30 seconds.', null, 'If the caster attacks the target, begins casting another Magical ability at the target or their carried equipment, or dies, this ability''s effect is negated.'),
(162, 'Throw', 'Verbal', 'Sorcery', '20''', null, '"My power throws thee" x3', 'Target player is moved 50'' in a straight line away from the caster. Works on Stopped players. If the caster is the target, the caster may choose the direction they move.', null, null),
(163, 'Tracking', 'Verbal', 'Sorcery', '20''', null, '"Tracking" x3', 'Target Insubstantial player immediately has their Insubstantial effect ended.', null, null),
(164, 'Trickery', 'Enchantment', 'Sorcery', 'Self', null, null, 'Bearer may cast Blink, Shadow Step, and Teleport on themselves while they are already Insubstantial, provided that they were the cause of the initial Insubstantial State and entered it voluntarily. Doing so removes the original Insubstantial effect.', null, null),
(165, 'Troll Blood', 'Enchantment', 'Protection', 'Other', 'Three white strips', '"The blood of the trolls sustains thee" x3', 'Enchanted player does not die as normal. When the player would otherwise die they instead ignore the triggering effect as though it had not occurred, remove a strip, and become Frozen for 30 seconds. The bearer is treated as though they have the effects of Regeneration in addition to the above.', null, 'Troll Blood is removed when the last strip is removed.'),
(166, 'True Grit', 'Verbal', 'Spirit', 'Self', null, '"The wicked flee when I pursue"', 'Player returns to life with their wounds healed and is immediately Frozen for 30 seconds', null, 'Enchantments on the player are retained.'),
(167, 'Undead Minion', 'Enchantment', 'Death', 'Other', 'Yellow strip', '
      "By the power of my will, arise my minion!" x5', 'Bearer is Cursed and cannot respawn. While the bearer is enchanted, the caster gains Raise Dead (Unlimited) (m) white can only be cast with the bearer as the target and ignores the requirement for the bearer to have not movedd from where they died. For the duration of the Enchantment, the bearer may treat the caster as a base for the purposes of the effects which require the bearer to go to their base. This Enchantment is Persistent, and remains active while the bearer is dead.', 'The caster may not have more than three Undead Minion Enchantments.', null),
(168, 'Vampirism', 'Enchantment', 'Death', 'Other', 'Yellow strip and white strip', '"Thy hunger can never be sated" x3', 'Player gains Adrenaline Unlimited (ex), is Immune to Death, and is Cursed. Bearer''s Adrenaline ability will work through their Cursed State.', null, null),
(169, 'Void Touched', 'Enchantment', 'Sorcery', 'Other', 'Red strip and white strip', '"Embrace the old ones and surrender thyself" x3', 'Bearer''s wielded melee weapons are Armor Breaking. Bearer gains Shadow Step 1/Refresh Charge x30 (ex), Steal Life Essence Unlimited (ex), and is unaffected by Magical abilities from the Sorcery, Spirit, and Death Schools. May still benefit from their own Steal Life Essence. Player is Cursed.', null, 'This effect does not interact with other Enchantments worn by the bearer.'),
(170, 'Ward Self', 'Enchantment', 'Protection', 'Self', 'White strip', '"The power of magic defends me" x3', 'Resistant to all effects from the next source which would inflict a wound, death, or State. Does not trigger against effects cast by the player.', null, null),
(171, 'Warder', 'Archetype', 'Neutral', null, null, null, 'All abilities purchased in the Protection School give double the uses. Example: 1/Life Charge x3 becomes 2/Life Charge x3, 2/Life becomes 4/Life.', 'Player may not purchase any abilities from the Death, Command, or Subdual Schools.', null),
(172, 'Warlock', 'Archetype', 'Neutral', null, null, null, 'Each Verbal purchased in the Death and Flame Schools gives double the uses. Example: 1/Life Charge x3 becomes 2/Life Charge x3, 2/Life becomes 4/Life.', 'Player may not purchase Verbals from any School other than the Death and Flame Schools.', null),
(173, 'Word of Mending', 'Verbal', 'Sorcery', 'Touch', null, '"Spedoinkle"', 'All equipment carried by target player is repaired. All armor worn by target player is restored to full value.', 'May not be cast within 20'' of a living enemy.', null),
(174, 'Wounding', 'Verbal', 'Death', '20''', null, '"Death strikes off thy [left/right] [arm/leg]" x3', 'Target hit location on target player is wounded.', 'Has no effect on players already wounded.', 'Wounding targets the player but affects the Hit Location. Visibility can be drawn to any part of the player, not just the desired Hit Location.'),
(175, 'Equipment: Weapon, Long', 'Neutral', null, null, null, null, 'May wield one Long weapon at a time for each instance purchased (but may carry extras).', null, null),
(176, 'Equipment: Weapon, Hinged', 'Neutral', null, null, null, null, 'May wield one Hinged weapon at a time for each instance purchased (but may carry extras).', null, null),
(177, 'Equipment: Weapon, Great', 'Neutral', null, null, null, null, 'May wield one Great weapon at a time for each instance purchased (but may carry extras).', null, null),
(178, 'Marauder', 'Archetype', 'Neutral', null, null, null, 'Gain Momentum Unlimited (ex) (Ambulant). Insult becomes 1/Life Charge x5 (m) (Ambulant).', 'Maximum Armor becomes 4pts. May not wield Large shields. Ancestral Armor is no longer chargeable.', null),
(179, 'Bear Strength', 'Enchantment', 'Sorcery', 'Other', 'Red strip', '"I enchant thee with the strength of the bear" x3', 'Bearer''s wielded melee weapons are Shield Crushing.', null, null),
(180, 'Imbue Weapon', 'Enchantment', 'Death', 'Other', 'Red strip', '"I enchant thee to slay all foes" x3', 'Bearer''s wielded melee weapons are Wounds Kill.', null, null),
(181, 'Rogue', 'Archetype', 'Neutral', null, null, null, 'Regain a use of Coup de Grace upon killing a player with a thrown weapon.', 'May not wield Long weapons or Bows.', null),
(182, 'Immune to Command', 'Trait', null, null, null, null, 'Player is Immune to Command.', null, null),
(183, 'Immune to Flame', 'Trait', null, null, null, null, 'Player is Immune to Flame.', null, null),
(184, 'Immune to Subdual', 'Trait', null, null, null, null, 'Player is Immune to Subdual.', null, null),
(185, 'Immune to Death', 'Trait', null, null, null, null, 'Player is Immune to Death.', null, null),
(186, 'Equipment: Armor, 1 Point', 'Neutral', null, null, null, null, 'Your class maximum armor limit increases one additional point.', null, null),
(187, 'Sacred Blades', 'Enchantment', 'Sorcery', 'Self', 'White strip and Red strip', '"I sanctify these weapons to smite the wicked" x2', 'Bearer''s wielded weapons are affected as per Harden. Bearer''s wielded melee weapons and any special effects delivered by them ignore magic armor and resistances that prevent wounds.', null, null),
(188, 'Ancestral Armor', 'Enchantment', 'Protection', 'Self', 'White strip', '"May this armor protect thee from all forms of harm"', 'The effects of a Magic Ball, projectile weapon, or melee weapon which just struck armor worn by the player are ignored, even if the object would not otherwise affect the armor. The armor loses one point of value in the location struck. This effect will not trigger if the armor has no points left in the location struck. Ancestral Armor is not expended after use and will continue to provide protection until removed with Dispel Magic or similar abilities.', 'Phase Arrow and Phase Bolt interact with armor worn by the bearer as though Ancestral Armor was not present.', 'Engulfing Effects that do not strike the bearers armor and abilities that ignore armor entirely do not trigger Ancestral Armor.'),
(189, 'Flame Blade', 'Enchantment', 'Flame', 'Self', 'Red strip and white strip', '"The element of fire shall infuse your weapons" x3', 'Bearer''s wielded melee weapons are Armor Breaking and Shield Crushing. Bearer and their wielded weapons are Immune to Flame.', null, null),
(190, 'Teleport', 'Verbal', 'Sorcery', 'Self', null, '"I travel through the aether" x5', 'Target willing player becomes Insubstantial and moves directly to a chosen location chosen by the caster at the time of casting. This must be a fixed location (not relative to a player or to a moveable object). Upon arrival, they must immediately end the effect as per Insubstantial.', null, 'If the player''s Insubstantial State is removed before they have reached their destination, the effects of Teleport end. If Teleport is cast on self, the caster may end this Insubstantial State at any time by using the exit incantation for Insubstantial.'),
(191, 'Trickery', 'Trait', null, null, null, null, 'Bearer may cast Blink, Shadow Step, and Teleport on themselves while they are already Insubstantial, provided that they were the cause of the initial Insubstantial State and entered it voluntarily. Doing so removes the original Insubstantial effect.', null, null),
(192, 'Berserk', 'Trait', null, null, null, null, 'Bearer''s wielded melee weapons are Armor Breaking.', null, null),
(193, 'Enlightened Soul', 'Trait', null, null, null, null, 'Player is unaffected by Verbal Magical abilities used at a Range greater than Touch.', 'Affects beneficial as well as harmful Magical abilities.', 'Does not affect (ex) abilities, abilities with a Range of Touch, nor abilities whose Range is greater than Touch but are used at a Range of Touch anyway.'),
(194, 'Missile Block', 'Trait', null, null, null, null, 'Player may block arrows, projectile weapons, and Magic Balls with their hands and wielded melee or thrown weapons. Any arrow, projectile weapon or magic ball blocked is nullified.', null, null),
(195, 'Protection from Magic', 'Enchantment', 'Protection', 'Touch', 'White strip', '"I enchant thee with protection from magic" x3', 'Bearer is unaffected by Magical abilities from any school. Upon death the player is Cursed.', null, 'This effect does not interact with other Enchantments worn by the bearer.'),
(196, 'Evolution', 'Trait', null, null, null, null, 'May wear an additional Enchantment. Evolution does not count towards the bearer''s Enchantment limit.', null, 'This ability does work in conjunction with Attuned, Essence Graft, or Phoenix Tears so long as the other limitations of those Enchantments are followed.'),
(197, 'Adaptive Protection', 'Enchantment', 'Protection', 'Self', 'White strip', '"I enchant thee with this protection" x3', 'Bearer becomes Immune to one of the following Schools: Death, Flame, Subdual, Command, Sorcery. School is chosen at the time of casting.', null, null),
(198, 'Harden', 'Enchantment', 'Protection', 'Self', 'White strip', '"I enchant thee with Harden" x3', 'Bearer''s wielded weapons or shield may only be destroyed or damaged by Magic Balls/Verbals which destroy objects e.g. Fireball or Pyrotechnics.', 'Will only affect either the weapons or the shield of the bearer, not both.', null),
(199, 'Imbue Armor', 'Trait', null, null, null, null, 'Armor worn by the bearer gains 1 Armor Point to its current and maximum rating in each location, up to the bearer''s class maximum.', 'Does not apply to Magic Armor. A player may only benefit from one instance of Imbue Armor.', 'When this enchantment is removed, the bearer loses 1 current and maximum Armor Point in each location.'),
(200, 'Phoenix Tears', 'Enchantment', 'Spirit', 'Self', 'Two white strips', '"May the tears of the phoenix wash over thee"', 'Enchanted player does not die as normal. When the player would otherwise die they instead remove a strip and become Frozen for 30 seconds. 
    
>>When the Frozen State is ended, the bearer is affected as follows:
    
>> 1. All wounds are removed.
    
>> 2. All States that would be removed by death or Respawning are removed.
    
>> 3. All Ongoing Effects with a timer expire.
    
>> 4. All of their carried equipment is fully repaired.
    
>> 5. All non-persistent enchantments, other than Phoenix Tears, are removed.
Additionally Phoenix Tears allows you to wear an extra Enchantment from the Protection School. This extra enchantment is considered Persistent as long as Phoenix Tears is present. The additional Enchantment is not removed once Phoenix Tears is removed.', 'Phoenix Tears is removed when the last strip is removed. If Phoenix Tears is removed, the bearer chooses which (m) Enchantments to lose to meet their new Enchantment limit, if necessary.', null),
(201, 'Poison Arrow', 'Specialty Arrow', 'Death', null, 'Arrow with green head cover labeled ''Poison''', '"Poison Arrow"', 'This arrow is Wounds Kill.', null, null)
on conflict (id) do update set
  name = excluded.name, type = excluded.type, school = excluded.school, range = excluded.range,
  materials = excluded.materials, incantation = excluded.incantation, effect = excluded.effect,
  limitation = excluded.limitation, note = excluded.note;

-- CLASSES: Idempotent without needing a unique constraint on name.
-- If your table uses different column names, adjust this block.

-- CLASS SPELL RULES: Full replace. WARNING: deletes all rows in public.class_spell_rules.
-- Safe if this table is only used as Swiftgard-derived catalog (no custom FKs from other tables).
delete from public.class_spell_rules;

;

commit;
